export const FAILURE_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: FAILURE_EASY_FOUNDATION,
    growth: FAILURE_EASY_GROWTH,
    mastery: FAILURE_EASY_MASTERY
  },
  medium: {
    foundation: FAILURE_MEDIUM_FOUNDATION,
    growth: FAILURE_MEDIUM_GROWTH,
    mastery: FAILURE_MEDIUM_MASTERY
  },
  hard: {
    foundation: FAILURE_HARD_FOUNDATION,
    growth: FAILURE_HARD_GROWTH,
    mastery: FAILURE_HARD_MASTERY
  },
};

export function getFailureStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = FAILURE_QUESTION_REGISTRY[diffKey] || FAILURE_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getFailureLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getFailureStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
